        if ($(this).is(':checked')) {
            $('#disclaimer-label span').css('color', '#64748b');
        }
    });

    // ==========================================
    // 0. 穿透引擎与API获取 (不变)
    // ==========================================
    const ST_WIN = window.parent || window || top;
    function getSTFn(fnName) {
        if (typeof ST_WIN[fnName] === 'function') return ST_WIN[fnName];
        if (typeof globalThis !== 'undefined' && typeof globalThis[fnName] === 'function') return globalThis[fnName];
        return null;
    }

    const api_getCharWorldbookNames = getSTFn('getCharWorldbookNames');
    const api_getWorldbook = getSTFn('getWorldbook');
    const api_updateWorldbookWith = getSTFn('updateWorldbookWith');
    const api_getLastMessageId = getSTFn('getLastMessageId');

    function tryApplyStoryLogic(stat_data) {
        let fn = getSTFn('calculateStoryLogic');
        if (typeof fn === 'function') {
            try { return fn(stat_data); } catch (e) { console.warn("Story Logic Sync Failed:", e); }
        }
        return stat_data;
    }

    // ==========================================
    // 1. 状态管理 (不变)
    // ==========================================
    let cachedStoryMap = null;
    let targetBookName = null;
    let initEntryUid = null;    // [initvar]
    let openingEntryUid = null; // [opening]
    let cachedOpeningContent = "";

    // UI 内部状态
    let state = {
        isRover: true,
        myGender: '男',
        npcGender: '女'
    };

    // ==========================================
    // 2. UI 渲染逻辑 (动效优化)
    // ==========================================
    function renderGenderSelector() {
        const $container = $('#gender-selection-area');
        let html = '';

        if (state.isRover) {
            html = `
            <div class="gender-grid rover-mode">
