                <div class="gender-card ${state.myGender === '女' ? 'selected' : ''}" onclick="window.selectMyGender('女')" id="my-card-female">
                    <div class="img-wrap"><img src="https://s41.ax1x.com/2026/02/25/pZxkJ2V.png"></div>
