    // ==========================================
    // 4. 环境检测与数据读取
    // ==========================================
    async function detectEnvironment() {
        let envStatus = true;
        let errMsg = [];

        try {
            const timeoutPromise = new Promise((_, reject) => setTimeout(() => reject(new Error("Timeout")), 3000));
            if (typeof ST_WIN.waitGlobalInitialized === 'function') {
                await Promise.race([ST_WIN.waitGlobalInitialized('Mvu'), timeoutPromise]);
            } else if (typeof globalThis.waitGlobalInitialized === 'function') {
                await Promise.race([globalThis.waitGlobalInitialized('Mvu'), timeoutPromise]);
            }
        } catch(e) {
            console.warn("Mvu Wait Timeout 或 MVU 未加载:", e);
        }

        const sources = [ ST_WIN, typeof globalThis !== 'undefined' ? globalThis : null ];
        for (const src of sources) {
            if (src && src.WuWaShared && src.WuWaShared.STORY_MAP) {
                cachedStoryMap = src.WuWaShared.STORY_MAP;
                break;
            }
        }

        if (!cachedStoryMap) { envStatus = false; errMsg.push("未读取到全局 STORY_MAP (修复建议：请检查是否正确导入并开启了相关酒馆助手角色脚本)"); }

        if (!api_getCharWorldbookNames || !api_getWorldbook || !api_updateWorldbookWith) {
            envStatus = false; errMsg.push("无法获取世界书 API (修复建议：请检查酒馆版本及助手插件状态)");
        } else {
            try {
                const charBooks = api_getCharWorldbookNames('current');
                if (charBooks && charBooks.primary) {
                    targetBookName = charBooks.primary;
                    const entries = await api_getWorldbook(targetBookName);

                    const initEntry = entries.find(e => (e.key && e.key.includes('[initvar]')) || (e.name && e.name.includes('[initvar]')));
                    if (initEntry) {
                        initEntryUid = initEntry.uid;
                    } else {
                        envStatus = false; errMsg.push("未找到 [initvar] 条目 (修复建议：请检查角色世界书内容是否完整导入)");
                    }

                    const openEntry = entries.find(e => (e.key && e.key.includes('[opening]')) || (e.name && e.name.includes('[opening]')));
                    if (openEntry) {
                        openingEntryUid = openEntry.uid;
                        cachedOpeningContent = openEntry.content || "";
                    } else {
                        toastr.warning("未找到 [opening] 条目，UI 状态无法保存。建议新建一个名为 [opening] 的空条目。");
                    }
                } else {
                    envStatus = false; errMsg.push("未绑定主世界书 (修复建议：请检查是否正确导入了角色世界书，并在当前角色卡中绑定)");
                }
            } catch (e) {
                envStatus = false; errMsg.push("世界书读取错误: " + e.message + " (修复建议：请尝试重新刷新酒馆网页)");
            }
        }

        const $status = $('#sys-status');
        if (envStatus) {
            $status.text("环境就绪").removeClass('status-err').addClass('status-ok');
        } else {
            $status.text("异常: " + errMsg.join(" | ")).removeClass('status-ok').addClass('status-err');
        }
    }

    // ==========================================
    // 5. 初始化回显
    // ==========================================
    function initializeUI() {
        const $verSelect = $('#ww-story-version');
        $verSelect.empty();
        if (cachedStoryMap) {
            cachedStoryMap.forEach((verObj, majorIdx) => {
                verObj.parts.forEach((title, partIdx) => {
                    $verSelect.append(`<option value="${majorIdx},${partIdx}">v${verObj.version} Part ${partIdx + 1}: ${title}</option>`);
                });
            });
        }

        const yaml = cachedOpeningContent;
        if (yaml) {
            const isRoverM = yaml.match(/^\s*UI_PlayRover:\s*(true|false)/m);
            if (isRoverM) state.isRover = (isRoverM[1] === 'true');

            const myGenM = yaml.match(/^\s*UI_MyGender:\s*"?([^"\r\n]+)"?/m);
            if (myGenM) state.myGender = myGenM[1];

            const npcExistM = yaml.match(/^\s*UI_NpcExist:\s*(true|false)/m);
            if (npcExistM) $('#ww-npc-exists').prop('checked', npcExistM[1] === 'true').trigger('change');

            const npcGenM = yaml.match(/^\s*UI_NpcGender:\s*"?([^"\r\n]+)"?/m);
            if (npcGenM) state.npcGender = npcGenM[1];

            const isStoryM = yaml.match(/^\s*UI_IsStoryMode:\s*(true|false)/m);
            if (isStoryM) $('#ww-is-story-mode').prop('checked', isStoryM[1] === 'true').trigger('change');

            const locMain = yaml.match(/^\s*所在区域:\s*"?([^"\r\n]+)"?/m);
            if (locMain) $('#ww-location-main').val(locMain[1]);

            const locDet = yaml.match(/^\s*详细地点:\s*"?([^"\r\n]*)"?/m);
            if (locDet) $('#ww-location-detail').val(locDet[1]);

            const targetChar = yaml.match(/^\s*目标角色:\s*"?([^"\r\n]*)"?/m);
            if (targetChar) $('#ww-target-char').val(targetChar[1]);

            const extraPlot = yaml.match(/^\s*补充剧情:\s*"?([^"\r\n]*)"?/m);
            if (extraPlot) $('#ww-plot-extra').val(extraPlot[1]);

            const customId = yaml.match(/^\s*UI_CustomIdentity:\s*"?((?:[^"\\]|\\.)*)"?/m);
            if (customId) $('#ww-custom-identity').val(customId[1].replace(/\\"/g, '"'));

            const aiRefine = yaml.match(/^\s*UI_AiRefine:\s*(true|false)/m);
            if (aiRefine) $('#ww-ai-refine').prop('checked', aiRefine[1] === 'true');

            const storyVer = yaml.match(/^\s*UI_StoryVer:\s*"?([^"\r\n]+)"?/m);
            if (storyVer) $verSelect.val(storyVer[1]);

            const storyStg = yaml.match(/^\s*UI_StoryStage:\s*"?([^"\r\n]+)"?/m);
            if (storyStg) $('#ww-story-stage').val(storyStg[1]);
        }

        $('#ww-play-rover').prop('checked', state.isRover);
        renderGenderSelector();
        updateNpcGenderUI();

        if (!state.isRover) {
            $('#ooc-warning').show();
            $('#ai-refine-container').show();
        }

        startIntroAnimation();
    }

    function startIntroAnimation() {
        $('.wuwa-logo-container').css('animation', 'logoIntro 1.2s cubic-bezier(0.22, 1, 0.36, 1) forwards');
        $('.wuwa-grid').css('animation', 'fadeInUp 0.8s ease 0.6s forwards');
        $('.action-row').css('animation', 'fadeInUp 0.6s ease 1.0s forwards');
        $('.status-bar-bottom').css('animation', 'fadeInUp 0.6s ease 1.2s forwards');
    }

    // ==========================================
    // 6. 提交逻辑
    // ==========================================
    function safeReplace(yamlString, key, newValue) {
        const regex = new RegExp(`(^\\s*${key}\\s*:)(.*)$`, 'm');
        if (!regex.test(yamlString)) return yamlString;
        return yamlString.replace(regex, function(match, prefixGroup) {
            return prefixGroup + ' ' + newValue;
        });
    }

    async function forceUpdateFloorZero(config, storyLocTitle) {
        const MvuObj = ST_WIN.Mvu || globalThis.Mvu;
        const TH = ST_WIN.TavernHelper || globalThis.TavernHelper;

        if (!MvuObj && !TH) {
            toastr.warning("未检测到 Mvu 框架，第0层变量无法即时修改。");
            return;
        }

        let targetData = {};
        let useMvu = !!MvuObj;

        try {
            if (useMvu) {
                const mData = await MvuObj.getMvuData({ type: 'message', message_id: 0 });
                targetData = mData.stat_data || {};
            } else {
                const vars = await TH.getVariables({ type: 'message', message_id: 0 });
                targetData = vars.stat_data || {};
            }
        } catch(e) { console.warn("0楼读取失败", e); }

        if (!targetData._storyState) targetData._storyState = {};
        targetData._storyState.majorVerIdx = config.majorVerIdx;
        targetData._storyState.partIdx = config.partIdx;
        targetData._storyState.isPostScript = config.isPostScript;
        targetData._storyState._anchorVer = config.anchorVerStr;

        if (!targetData.指令) targetData.指令 = {};
        targetData.指令.推进剧情 = null; targetData.指令.跳转版本 = null; targetData.指令.修改后日谈模式为 = null;

        targetData.剧情显示 = storyLocTitle;
        targetData.是否为后日谈 = String(config.isPostScript);

        if (!targetData.主角信息) targetData.主角信息 = {};
        targetData.主角信息.是否是漂泊者 = config.isRover;
        targetData.主角信息.性别 = config.myGender;
        targetData.主角信息.身份与额外设定 = config.identity;

        if (!targetData.NPC漂泊者) targetData.NPC漂泊者 = {};
        targetData.NPC漂泊者.是否存在 = config.npcExists;
        if (config.npcExists) targetData.NPC漂泊者.性别 = config.npcGender;

        targetData = tryApplyStoryLogic(targetData);

        try {
            if (useMvu) await MvuObj.replaceMvuData({ stat_data: targetData }, { type: 'message', message_id: 0 });
            else await TH.updateVariablesWith((vars) => { vars.stat_data = targetData; return vars; }, { type: 'message', message_id: 0 });
            toastr.success('✅ 开场数据已就绪！');
        } catch (e) { toastr.error('数据写入失败: ' + e.message); }
    }

    $('#ww-start-btn').on('click', async function(e) {
        e.preventDefault();

        const charTarget = ($('#ww-target-char').val() || "").trim().replace(/[\r\n]+/g, ' ');
        if (!charTarget) {
            toastr.error("❌ 初始化失败：必须填写“开局见到的角色”！<br>若不清楚，请查阅对应剧情版本的世界书。", {escapeHtml:false, timeOut: 5000});
            $('#ww-target-char').focus().css('border-color', '#fc8181');
            return;
        }

        const npcExists = $('#ww-npc-exists').is(':checked');
        const customInput = ($('#ww-custom-identity').val() || "").trim().replace(/[\r\n]+/g, ' ');
        const wantAiRefine = !state.isRover && $('#ww-ai-refine').is(':checked');

        let finalIdentity = "";
        if (state.isRover) {
            finalIdentity = "寻找归途与失落记忆，且背负着文明火种与救世使命的漂泊者。" + customInput;
        } else {
            if (customInput) {
                finalIdentity = customInput;
            } else {
                finalIdentity = "你是一名来自异世界的穿越者，在意外中降临此世。虽然没有悲鸣赋予的声痕，却意外觉醒了与频率共鸣的能力。你是这个世界的变数，也是未被观测的星火。";
            }
            if (wantAiRefine) {
                finalIdentity += " (等待AI根据用户指令重写并完善...)";
            }
        }

        const isStory = $('#ww-is-story-mode').is(':checked');
        let majorVerIdx = 13; let partIdx = 3; let isPostScript = true;
        let storyLocTitle = "v3.0 Part 4 后日谈模式";
        let storyStageStr = "后日谈";
        let uiStoryVer = "";

        if (!isStory && cachedStoryMap && cachedStoryMap.length > 0) {
            const latestVer = cachedStoryMap[cachedStoryMap.length - 1];
            majorVerIdx = cachedStoryMap.length - 1;
            partIdx = latestVer.parts.length - 1;
            isPostScript = true;
            const cleanTitle = latestVer.parts[partIdx].replace(/\s*[（\(](上|中|下)[）\)]/g, '');
            storyLocTitle = `v${latestVer.version} 后日谈: ${cleanTitle} (已完结)`;
        }

        if (isStory) {
            uiStoryVer = $('#ww-story-version').val();
            const indices = uiStoryVer.split(',');
            if (indices.length === 2) {
                majorVerIdx = parseInt(indices[0]); partIdx = parseInt(indices[1]);
            }
            storyStageStr = $('#ww-story-stage').val();
            isPostScript = (storyStageStr === '后日谈');
            storyLocTitle = $('#ww-story-version option:selected').text();
        }

        const targetVerObj = cachedStoryMap ? cachedStoryMap[majorVerIdx] : null;
        const anchorVerStr = targetVerObj ? targetVerObj.version : (cachedStoryMap && cachedStoryMap.length > 0 ? cachedStoryMap[cachedStoryMap.length - 1].version : '3.0');

        const config = {
            majorVerIdx, partIdx, isPostScript, anchorVerStr,
            isRover: state.isRover,
            myGender: state.myGender,
            identity: finalIdentity.replace(/"/g, '\\"'),
            npcExists, npcGender: state.npcGender
        };

        const locMain = $('#ww-location-main').val();
        const locDetail = ($('#ww-location-detail').val() || "").trim().replace(/[\r\n]+/g, ' ');
        const plotExtra = ($('#ww-plot-extra').val() || "").trim().replace(/[\r\n]+/g, ' ');

        await forceUpdateFloorZero(config, storyLocTitle);

        try {
            await api_updateWorldbookWith(targetBookName, (entries) => {
                return entries.map(entry => {
                    if (entry.uid === initEntryUid) {
                        let c = entry.content || "";
                        c = safeReplace(c, 'majorVerIdx', config.majorVerIdx);
                        c = safeReplace(c, 'partIdx', config.partIdx);
                        c = safeReplace(c, 'isPostScript', config.isPostScript);
                        c = safeReplace(c, '_anchorVer', `"${config.anchorVerStr}"`);

                        let blocks = c.split('NPC漂泊者:');
                        if (blocks.length > 0) {
                            blocks[0] = safeReplace(blocks[0], '是否是漂泊者', config.isRover);
                            blocks[0] = safeReplace(blocks[0], '性别', `"${config.myGender}"`);
                            blocks[0] = safeReplace(blocks[0], '身份与额外设定', `"${config.identity}"`);
                        }
                        if (blocks.length > 1) {
                            blocks[1] = safeReplace(blocks[1], '是否存在', config.npcExists);
                            blocks[1] = safeReplace(blocks[1], '性别', `"${config.npcGender}"`);
                        }
                        return { ...entry, content: blocks.join('NPC漂泊者:') };
                    }

                    if (openingEntryUid !== null && entry.uid === openingEntryUid) {
                        const openingYaml =
`UI_PlayRover: ${state.isRover}
UI_MyGender: "${state.myGender}"
UI_NpcExist: ${npcExists}
UI_NpcGender: "${state.npcGender}"
UI_IsStoryMode: ${isStory}
UI_StoryVer: "${uiStoryVer}"
UI_StoryStage: "${storyStageStr}"
UI_CustomIdentity: "${customInput.replace(/"/g, '\\"')}"
UI_AiRefine: ${wantAiRefine}
所在区域: "${locMain}"
详细地点: "${locDetail.replace(/"/g, '\\"')}"
目标角色: "${charTarget.replace(/"/g, '\\"')}"
补充剧情: "${plotExtra.replace(/"/g, '\\"')}"`;
                        return { ...entry, content: openingYaml };
                    }
                    return entry;
                });
            }, { render: 'immediate' });
        } catch (err) { toastr.error('世界书写入异常: ' + err.message); return; }

        const locFinal = locDetail ? locDetail : "自由发挥";
        const plotFinal = plotExtra ? plotExtra : "自由发挥";

        let finalPrompt =
            "<status>\n" +
            "[系统指令：生成开场剧情]\n" +
            "1. 剧情定位：" + storyLocTitle + " (" + storyStageStr + ")\n" +
            "2. 地点：" + locMain + "-" + locFinal + "\n" +
            "3. 主角设定：" + state.myGender + "性, " + finalIdentity + "\n" +
            "4. 初始情境：" + plotFinal + "\n" +
            "5. 互动角色：" + charTarget + "\n\n";

        if (wantAiRefine) {
            finalPrompt += "6. 检测到用户提供了自定义设定，请基于用户的描述，重新生成并完善【身份与额外设定】变量，使其包含外貌、能力、性格等细节。\n\n";
        }

        finalPrompt +=
            "请根据上述设定，直接开始描写开场剧情。\n" +
            "请聚焦于环境描写、角色登场以及主角的感官体验。\n" +
            "如果前文没有特别要求，登场角色无论是谁，都应该穿着其默认装扮。\n" +
            "</status>";

        try {
            function getChatInput() {
                if (typeof document !== 'undefined') {
                    const el = document.querySelector('#send_textarea');
                    if (el) return el;
                }
                if (typeof ST_WIN !== 'undefined' && ST_WIN.document) {
                    const el = ST_WIN.document.querySelector('#send_textarea');
                    if (el) return el;
                }
                return null;
            }

            const inp = getChatInput();
            if (inp) {
                const cur = inp.value.trim();
                inp.value = cur ? cur + '\n' + finalPrompt : finalPrompt;
                inp.dispatchEvent(new Event('input', { bubbles: true }));
                toastr.info('已生成情景引导并注入聊天框，请手动发送开始游戏。');
            } else {
                toastr.warning('配置已保存，但未能定位到聊天输入框。');
            }
        } catch (err) { console.warn(err); }
    });

    await detectEnvironment();
    initializeUI();
});
</script>
